import org.jsoup.helper.UrlBuilder;
import org.jsoup.util.Connection;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;

import java.io.IOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;

import static org.mockito.Mockito.when;

@RunWith(JUnit4.class)
public class UrlBuilderTest {

    @Test
    public void build_ValidUrl_ReturnsValidUrl() {
        UrlBuilder urlBuilder = new UrlBuilder("http://example.com");
        URL expectedUrl = new URL("http://example.com");
        when(urlBuilder.inputUrl()).thenReturn(expectedUrl);
        URL actualUrl = urlBuilder.build();
        assertEquals(expectedUrl, actualUrl);
    }

    @Test
    public void build_InvalidUrl_ThrowsNullPointerException() {
        UrlBuilder urlBuilder = new UrlBuilder(null);
        NullPointerException expectedException = new NullPointerException("Input URL is null");
        assertThrows(expectedException::getMessage, () -> urlBuilder.build());
    }

    @Test
    public void appendKeyVal_AddsKeyAndValueToUrl() throws IOException {
        UrlBuilder urlBuilder = new UrlBuilder(new URL("http://example.com"));
        Connection.KeyVal kv = new Connection.KeyVal("key", "value");
        String expectedUrl = "http://example.com?key=value";
        when(urlBuilder.inputUrl()).thenReturn(new URL("http://example.com"));
        String actualUrl = urlBuilder.appendKeyVal(kv).toString();
        assertEquals(expectedUrl, actualUrl);
    }

    @Test
    public void appendKeyVal_ThrowsUnsupportedEncodingException() {
        UrlBuilder urlBuilder = new UrlBuilder(new URL("http://example.com"));
        Connection.KeyVal kv = new Connection.KeyVal("key", "value");
        UnsupportedEncodingException expectedException = new UnsupportedEncodingException();
        assertThrows(expectedException::getMessage, () -> urlBuilder.appendKeyVal(kv));
    }

    @Test
    public void appendKeyVal_AddsMultipleKeysAndValuesToUrl() throws IOException {
        UrlBuilder urlBuilder = new UrlBuilder(new URL("http://example.com"));
        Connection.KeyVal kv1 = new Connection.KeyVal("key1", "value1");
        Connection.KeyVal kv2 = new Connection.KeyVal("key2", "value2");
        String expectedUrl = "http://example.com?key1=value1&key2=value2";
        when(urlBuilder.inputUrl()).thenReturn(new URL("http://example.com"));
        String actualUrl = urlBuilder.appendKeyVal(kv1).appendKeyVal(kv2).toString();
        assertEquals(expectedUrl, actualUrl);
    }
}
